export function balanceChart(game,compact=false){const current=game.stock-game.initial,points=[...game.balanceHistory,{time:game.time,value:current}],maxTime=Math.max(1,game.time),low=Math.min(-10,...points.map(p=>p.value)),high=Math.max(10,...points.map(p=>p.value)),x=t=>48+t/maxTime*492,top=compact?12:20,bottom=compact?64:160,y=v=>top+(high-v)/(high-low)*(bottom-top),path=points.map((p,i)=>`${i?'L':'M'}${x(p.time).toFixed(1)},${y(p.value).toFixed(1)}`).join(' '),signed=n=>(n>0?'+':'')+Math.round(n).toLocaleString('ja-JP');return `<div class="balance-heading"><span>差玉の推移</span><b>${signed(current)}玉</b></div><svg class="balance-chart" viewBox="0 0 560 ${compact?92:192}" role="img" aria-label="開始時からの持ち玉の増減。現在${signed(current)}玉"><path d="M48 ${y(0)}H540" stroke="#b4c0d1" stroke-dasharray="4 5" opacity=".6"/><path d="M48 ${top}V${bottom}H540" fill="none" stroke="#3e5369"/><text x="43" y="${top+5}" text-anchor="end">${signed(high)}</text><text x="43" y="${bottom+3}" text-anchor="end">${signed(low)}</text><text x="48" y="${bottom+22}">開始</text><text x="540" y="${bottom+22}" text-anchor="end">${Math.floor(maxTime/60)}分${Math.floor(maxTime%60)}秒</text><path d="${path}" stroke="${current>=0?'#80def5':'#ef967d'}" stroke-width="2.5" fill="none"/><circle cx="${x(game.time)}" cy="${y(current)}" r="4" fill="#fff1c6"/></svg><p class="chart-note">持ち玉 − 開始時の持ち玉。補給・返却を含みます。</p>`;}
